        uint128 virtualBaseTokenReservesArg,
        uint128 virtualNftReservesArg,
        uint56 changeFeeArg,
        uint16 feeRateArg,
        bytes32 merkleRootArg,
        bool useStolenNftOracleArg,
        bool payRoyaltiesArg
    ) public payable {
        require(feeRateArg <= 5_000);

        c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        );

        bool initializedBefore = c.initialized();
        uint16 rateBefore = c.feeRate();

